message.content:
{
  "title": "The Rescue of the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A torn map points the way into the dead city.",
      "visual_description": "Dawn light over a ridge; a cloaked figure unrolls a brittle map showing a ruined royal city in the valley below, banners faded on broken towers.",
      "characters": ["Maren the Pathfinder"]
    },
    {
      "scene_number": 2,
      "caption": "The team gathers at the edge of the ruins.",
      "visual_description": "Five travelers crouched in tall grass at the city outskirts, packs and weapons ready, a crumbling outer wall behind them.",
      "characters": ["Maren the Pathfinder", "Sir Doral", "Vesh the Quiet", "Old Bramley", "Lios the Spellwright"]
    },
    {
      "scene_number": 3,
      "caption": "The castle gates loom, too obvious to trust.",
      "visual_description": "Massive iron-bound gates standing half-open, scorch marks on the stone, suspiciously unbarred; the team studies them from a doorway across the plaza.",
      "characters": ["Maren the Pathfinder", "Sir Doral"]
    },
    {
      "scene_number": 4,
      "caption": "Old Bramley argues for a nap and a side road.",
      "visual_description": "A round, gray-bearded official in rumpled robes yawning and gesturing at a narrow alley, while the others look exasperated.",
      "characters": ["Old Bramley", "Maren the Pathfinder", "Sir Doral"]
    },
    {
      "scene_number": 5,
      "caption": "Vesh slips ahead to scout the patrol routes.",
      "visual_description": "A lithe scout in dark leathers climbing along a broken parapet, watching torch-lit armored patrols march in the street below.",
      "characters": ["Vesh the Quiet"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower whispers promises of treasure.",
      "visual_description": "A leaning black tower wreathed in violet mist; faint ghostly hands beckon from its windows as the group passes warily on the cobbles.",
      "characters": ["Lios the Spellwright", "Maren the Pathfinder", "Sir Doral", "Old Bramley"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople beg for help they cannot give.",
      "visual_description": "A ragged family huddled in a doorway, candle-lit, reaching out as the rescuers pause; broken pottery and a fallen royal banner on the street.",
      "characters": ["Maren the Pathfinder", "Old Bramley", "Townsfolk Mother", "Townsfolk Child"]
    },
    {
      "scene_number": 8,
      "caption": "Old Bramley shares his last bread with the child.",
      "visual_description": "The sleepy official kneeling, pressing a heel of bread into a small child's hands, his eyes unusually awake and kind.",
      "characters": ["Old Bramley", "Townsfolk Child"]
    },
    {
      "scene_number": 9,
      "caption": "Rumor of a dragon nesting in the keep.",
      "visual_description": "A scorched square with enormous claw marks on the flagstones and a shed scale the size of a shield; the team examines it under low red clouds.",
      "characters": ["Sir Doral", "Lios the Spellwright", "Maren the Pathfinder"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrol marches through the plaza.",
      "visual_description": "A column of helmed soldiers in tarnished royal livery passing a fountain; the rescuers press flat against a colonnade in shadow.",
      "characters": ["Vesh the Quiet", "Sir Doral", "Patrol Captain"]
    },
    {
      "scene_number": 11,
      "caption": "Lios reads the sealed magic door.",
      "visual_description": "An arched door inlaid with glowing silver runes in a mossy courtyard; the spellwright traces sigils in the air, light reflecting on his spectacles.",
      "characters": ["Lios the Spellwright", "Maren the Pathfinder"]
    },
    {
      "scene_number": 12,
      "caption": "The door opens onto the throne hall.",
      "visual_description": "A vast ruined hall with shattered stained glass, dust motes in slanting light, a cracked throne, and faded royal banners hanging in tatters.",
      "characters": ["Lios the Spellwright", "Sir Doral", "Maren the Pathfinder", "Vesh the Quiet", "Old Bramley"]
    },
    {
      "scene_number": 13,
      "caption": "They find Princess Aelinor chained beneath the throne.",
      "visual_description": "A young woman in torn finery shackled at the base of the dais, lifting her head as lantern light finds her; relief and fear in her eyes.",
      "characters": ["Princess Aelinor", "Sir Doral", "Maren the Pathfinder"]
    },
    {
      "scene_number": 14,
      "caption": "The dragon stirs above the rafters.",
      "visual_description": "A great scaled coil shifting in the broken roof beams; one molten eye opens, glowing on the dust below.",
      "characters": ["Princess Aelinor", "Sir Doral", "Lios the Spellwright", "The Ruin Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "Sir Doral holds the doorway while the others flee.",
      "visual_description": "The knight braced in a narrow archway, shield raised against a gout of orange flame curling around the stone, silhouette against fire.",
      "characters": ["Sir Doral", "The Ruin Dragon"]
    },
    {
      "scene_number": 16,
      "caption": "Vesh leads them along the rooftops to the river.",
      "visual_description": "Figures leaping from a collapsing tile roof to a lower wall, the dark river glinting ahead between buildings, smoke rising behind.",
      "characters": ["Vesh the Quiet", "Princess Aelinor", "Maren the Pathfinder", "Lios the Spellwright", "Old Bramley"]
    },
    {
      "scene_number": 17,
      "caption": "Old Bramley spans the broken bridge with a yawning spell.",
      "visual_description": "The sleepy official, suddenly luminous, breathes a shimmering arc of pale light across a shattered stone bridge over a black river; the others run across.",
      "characters": ["Old Bramley", "Princess Aelinor", "Maren the Pathfinder", "Vesh the Quiet", "Lios the Spellwright", "Sir Doral"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, they look back at the burning city.",
      "visual_description": "The group on a green hillside at sunrise, the ruined city smoking in the valley; the princess wrapped in Doral's cloak, Bramley already dozing on his pack.",
      "characters": ["Princess Aelinor", "Sir Doral", "Maren the Pathfinder", "Vesh the Quiet", "Lios the Spellwright", "Old Bramley"]
    }
  ]
}

